from __future__ import annotations

import base64
from pathlib import Path

# Demo enrollment face embedded in source so Render Free can recreate it
# after a restart. The Free filesystem is ephemeral.
_SEED_FACES = {
    "uzair/uzair.jpg": """"""
}


def ensure_seed_faces(known_faces_dir: Path) -> None:
    for relative_path, encoded in _SEED_FACES.items():
        target = known_faces_dir / relative_path
        if not target.exists():
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(base64.b64decode(encoded))
